head.script:
/**
 * @component
 * @componentName udc_bulkFileSaver
 * @pluginName 
 * @company Inswave
 * @developer Inswave
 * @category /cm/udc
 * @notSupportBrowser 
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @description dataList 신규/수정 로우 + 파일을 하나의 XHR 로 저장하는 공통 UDC.
 *              내부에 히든 multiupload 를 포함해 파일 다이얼로그 트리거 + File 저장소 관리.
 * @width
 * @height
 * @license
 * @imagePath
 * @homepage
 */

/**
 * @property
 * @name id
 * @category 01.Basic & ETC
 * @type string
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트의 ID 를 설정합니다.
 */

/**
 * @property
 * @name class
 * @category 01.Basic & ETC
 * @type string
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트에 적용하려는 클래스의 이름을 설정합니다.
 */

/**
 * @property
 * @name style
 * @category 01.Basic & ETC
 * @type string
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트에 적용하려는 style을 설정합니다.
 */

/**
 * @property
 * @name fileNameColumn
 * @category 03.Data
 * @type string
 * @option
 * @default fileName
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description [Default : fileName] 파일명의 컬럼 아이디
 */

/**
 * @property
 * @name fileSizeColumn
 * @category 03.Data
 * @type string
 * @option
 * @default fileSize
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description [Default : fileSize] 파일사이즈 컬럼명 설정
 */

// ═══════════════════════════════════════════════════════════════
// 라이프사이클
// ═══════════════════════════════════════════════════════════════

/**
 * @event 
 * @name onwframeload
 * @description 화면이 열리기 전 발생하는 이벤트. UDC 초기화에 필요한 코드를 작성한다.
 */
scwin.onwframeload = function () {
	scwin.option = $p.getOptions({});
	// uid → File 매핑
	scwin.fileMap = {};
	// 파일 다이얼로그 오픈 시 컨텍스트 (부모 dataList + rowIdx)
	scwin.ctx = { rowIdx: -1, dataList: null };
};

/**
 * @event 
 * @name onpageload
 * @description 화면이 열렸을 때 엔진 초기화 작업이 끝난 뒤에 발생하는 이벤트. 화면 초기화에 필요한 코드를 작성한다.
 */
scwin.onpageload = function () { 
	if ($c.util.isEmpty(scwin.option.fileNameColumn)) { scwin.option.fileNameColumn = "fileName"; }
	if ($c.util.isEmpty(scwin.option.fileSizeColumn)) { scwin.option.fileSizeColumn = "fileSize"; }
};

/**
 * @method 
 * @name getUdcObj
 * @description UDC 자신 참조
 * @hidden N
 * @return UDC 참조 리턴
 */
scwin.getUdcObj = function () {
	const frame = $p.getFrame();
	if (!$c.util.isEmpty(frame.udc2Parent)) return frame.udc2Parent;
	return frame;
};

// ═══════════════════════════════════════════════════════════════
// 파일 첨부/제거 (부모에서 호출)
// ═══════════════════════════════════════════════════════════════

/**
 * @method 
 * @name attachFile
 * @description 지정 행에 파일 첨부 다이얼로그 오픈.
 * @param {number} rowIdx    그리드 행 인덱스
 * @hidden N
 * @param {object} dataList  부모 dataList (uid/fileName/fileSize/fileChanged 컬럼 필요)
 */
scwin.attachFile = function (rowIdx, dataList) {
	scwin.ctx.rowIdx = rowIdx;
	scwin.ctx.dataList = dataList;
	if (!mpu_hidden.dom || !mpu_hidden.dom.inputZone) {
		$c.win.alert("업로드 컴포넌트 초기화 오류"); return;
	}

	mpu_hidden.dom.inputZone.value = "";
	mpu_hidden.dom.inputZone.click();
};

/**
 * @method 
 * @name detachFile
 * @description 지정 행의 파일 제거 (fileChanged=Y 세팅)
 * @param {number} rowIdx    그리드 행 인덱스
 * @hidden N
 * @param {object} dataList  부모 dataList (uid/fileName/fileSize/fileChanged 컬럼 필요)
 */
scwin.detachFile = function (rowIdx, dataList) {
	const uid = dataList.getCellData(rowIdx, "uid");
	if (scwin.fileMap[uid]) {
		delete scwin.fileMap[uid];
	}

	dataList.setCellData(rowIdx, scwin.option.fileNameColumn, "");
	dataList.setCellData(rowIdx, scwin.option.fileSizeColumn, 0);
	dataList.setCellData(rowIdx, "fileChanged", "Y");
};

/**
 * @method 
 * @name selectCallback
 * @description multiupload selectCallback — File 획득 → fileMap 저장 + dataList 표시 갱신
 * @param {object} data  부모 dataList (uid/fileName/fileSize/fileChanged 컬럼 필요)
 * @hidden N
 */
scwin.selectCallback = function (data) {
	const ctx = scwin.ctx || {};
	scwin.ctx = { rowIdx: -1, dataList: null };
	if (!data || data.length === 0) return;

	const files = mpu_hidden.fileArray || [];
	const file = files[files.length - 1];
	if (!file) return;

	// 두 컨텍스트 지원 — dataList (rowIdx) or dataMap (fieldKey)
	if (ctx.dataList && ctx.rowIdx >= 0) {
		const uid = ctx.dataList.getCellData(ctx.rowIdx, "uid");
		scwin.fileMap[uid] = file;
		ctx.dataList.setCellData(ctx.rowIdx, scwin.option.fileNameColumn, file.name);
		ctx.dataList.setCellData(ctx.rowIdx, scwin.option.fileSizeColumn, file.size);
		ctx.dataList.setCellData(ctx.rowIdx, "fileChanged", "Y");
	} else if (ctx.dataMap && ctx.fieldKey) {
		scwin.fileMap[ctx.fieldKey] = file;
		ctx.dataMap.set(ctx.fieldKey, file.name);   // input(ref) 자동 갱신
	}

	mpu_hidden.removeFile(file.name);
};

/**
 * @method 
 * @name clearFileMap
 * @description fileMap 초기화 (필요 시 부모에서 호출)
 * @hidden N
 */
scwin.clearFileMap = function () {
	for (let k in scwin.fileMap) {
		if (scwin.fileMap.hasOwnProperty(k)) {
			delete scwin.fileMap[k];
		}
	};
};

/**
 * @method 
 * @name getFileMap
 * @description 내부 fileMap 참조 반환 (제너레이터 방식에서 임시 슬롯 조작용)
 * @hidden N
 * @return fileMap 내부 fileMap 리턴
 */
scwin.getFileMap = function () {
	return scwin.fileMap;
};

/**
 * @method 
 * @name transferFile
 * @description fileMap key 변경 (임시 슬롯 → 실제 uid 로 이동)
 * @hidden N
 */
scwin.transferFile = function (oldKey, newKey) {
	if (scwin.fileMap[oldKey]) {
		scwin.fileMap[newKey] = scwin.fileMap[oldKey];
		delete scwin.fileMap[oldKey];
	}
};

// ═══════════════════════════════════════════════════════════════
// 내부 헬퍼 — 단일/멀티 인자 정규화
// ═══════════════════════════════════════════════════════════════

/**
 * @method
 * @name __toArray
 * @description 단일 값/배열을 배열로 정규화한다. (빈 값은 빈 배열)
 * @hidden Y
 */
scwin.__toArray = function (v) {
	if ($c.util.isEmpty(v)) return [];
	return Array.isArray(v) ? v : [v];
};

/**
 * @method
 * @name __partName
 * @description FormData 파트 이름 결정 — 명시 id(단일/배열) 우선, 미지정 시 base, base2, base3…
 * @hidden Y
 */
scwin.__partName = function (ids, idx, base) {
	if (Array.isArray(ids)) {
		if (!$c.util.isEmpty(ids[idx])) return ids[idx];
	} else if (idx === 0 && !$c.util.isEmpty(ids)) {
		return ids;
	}
	return idx === 0 ? base : base + (idx + 1);
};

// ═══════════════════════════════════════════════════════════════
// 목록 조회
// ═══════════════════════════════════════════════════════════════

/**
 * @method 
 * @name loadList
 * @description GET 목록 조회 → mapper 변환 → dataList.setJSON
 * @param {Object}   opts
 * @hidden N
 * @param {Object}   opts.dataList
 * @param {string}   opts.listUrl
 * @param {Function} opts.mapper     서버 row → dataList row 변환
 * @param {string}   opts.listKey    응답 안 목록 배열 key (기본 "list")
 * @param {Function} opts.onSuccess
 * @param {Function} opts.onError
 */
scwin.loadList = async function (opts) {
	try {
		const res = await fetch(opts.listUrl).then(function (r) {
			if (!r.ok) throw new Error("HTTP " + r.status);
			return r.json();
		});

		const raw = res[opts.listKey || "list"] || [];
		const mapper = opts.mapper || function (r) { return r; };
		opts.dataList.setJSON(raw.map(mapper));

		if (typeof opts.onSuccess === "function") opts.onSuccess(res);
	} catch (e) {
		if (typeof opts.onError === "function") {
			opts.onError(e);
		} else {
			$c.win.alert("조회 실패: " + e.message);
		}
	}
};

/**
 * @method
 * @name save
 * @description 일괄 저장 — 신규(C)/수정(U)/삭제(D) 로우와 파일을 한 요청(multipart)으로 서버 전송.
 * dataList/dataMap 은 단일 또는 배열(멀티)로 전달할 수 있다.
 * FormData 구성:
 *   - dataList 별 파트: { "{파트명}": rows } JSON Blob ("{파트명}.json", application/json)
 *   - dataMap  별 파트: dataMap JSON Blob (opts.dataMap 지정 시)
 *   - files 파트: 같은 이름으로 여러 개 append
 * 파트 이름: dataListId/dataMapId(단일 문자열 또는 병렬 배열) 우선, 미지정 시 rows, rows2… / data, data2…
 * 매칭 : rows[i].fileIndex 로 files 의 i 번째 파일 참조(모든 dataList 공용 인덱스). 파일 없는 행은 fileIndex=null.
 * @param {Object}         opts
 * @hidden N
 * @param {Object|Array}   opts.dataList     단일 dataList 또는 배열(멀티)
 * @param {string}         opts.saveUrl
 * @param {boolean}        opts.sendAll      true 면 변경분(C/U/D) 대신 전체 로우 전송 (기본 false)
 * @param {string|Array}   opts.dataListId   rows 파트 이름 — 단일 문자열 또는 dataList 와 병렬인 배열 (기본 rows, rows2…)
 * @param {Object|Array}   opts.dataMap      (선택) 함께 전송할 dataMap — 단일 또는 배열(멀티)
 * @param {string|Array}   opts.dataMapId    dataMap 파트 이름 — 단일 문자열 또는 병렬 배열 (기본 data, data2…)
 * @param {Function}       opts.onValidate   row → err|null (모든 dataList 의 로우에 적용)
 * @param {Function}       opts.onSuccess    (res)
 * @param {Function}       opts.onAfterSave  (res)
 * @param {Function}       opts.onError
 * @example
// 1) 단일 dataList — 변경분(C/U/D)만 저장, 파일은 attachFile 로 첨부해 둔 것 자동 동봉
//    → FormData 파트: rows, files
udc_saver.getScope().save({
    dataList : dlt_list,
    saveUrl : "/api/x/bulk-save",
    onValidate : function (row) { return $c.util.isEmpty(row.title) ? "제목을 입력하세요." : null; },
    onAfterSave : async function (res) { await scwin.searchList(); }
});

// 2) 단일 dataList + 조회조건 dataMap 동봉 → 파트: rows, data, files
udc_saver.getScope().save({ dataList : dlt_list, dataMap : dma_search, saveUrl : "/api/x/bulk-save" });

// 3) 멀티 dataList/dataMap — 파트 이름은 병렬 배열로 지정(미지정 인덱스는 rows2/data2… 자동)
//    → 파트: master, rows2, cond, data2, files
udc_saver.getScope().save({
    dataList : [dlt_master, dlt_detail],
    dataListId : ["master"],              // 두 번째는 자동 "rows2"
    dataMap : [dma_search, dma_etc],
    dataMapId : ["cond"],                 // 두 번째는 자동 "data2"
    saveUrl : "/api/x/bulk-save",
    sendAll : true                        // 변경분 대신 전체 로우 전송
});
 */
scwin.save = async function (opts) {
	const dataLists = scwin.__toArray(opts.dataList);
	const listPayloads = [];
	let totalRows = 0;

	// dataList 별 payload 수집 (sendAll: 전체 / 기본: 변경분 C·U·D)
	for (let li = 0; li < dataLists.length; li++) {
		const dl = dataLists[li];
		const payload = [];

		if (opts.sendAll === true) {
			payload.push.apply(payload, dl.getAllJSON() || []);
		} else {
			const newRows = dl.getInsertedJSON() || [];
			const updRows = dl.getUpdatedJSON() || [];
			const delRows = dl.getDeletedJSON() || [];

			for (let n = 0; n < newRows.length; n++) { newRows[n].rowStatus = "C"; payload.push(newRows[n]); }
			for (let u = 0; u < updRows.length; u++) { updRows[u].rowStatus = "U"; payload.push(updRows[u]); }
			for (let d = 0; d < delRows.length; d++) { delRows[d].rowStatus = "D"; payload.push(delRows[d]); }
		}

		listPayloads.push(payload);
		totalRows += payload.length;
	}

	// if (dataLists.length > 0 && totalRows === 0) {
	// 	$c.win.alert(opts.sendAll === true ? "저장할 데이터가 없습니다." : "저장할 변경 사항이 없습니다.");
	// 	return;
	// }

	if (typeof opts.onValidate === "function") {
		for (let p = 0; p < listPayloads.length; p++) {
			for (let v = 0; v < listPayloads[p].length; v++) {
				const err = opts.onValidate(listPayloads[p][v]);
				if (err) { $c.win.alert(err); return; }
			}
		}
	}

	// 파일 있는 행에만 fileIndex 부여(모든 dataList 공용 files 배열 기준)
	const files = [];
	for (let p2 = 0; p2 < listPayloads.length; p2++) {
		const payload = listPayloads[p2];
		for (let i = 0; i < payload.length; i++) {
			const row = payload[i];
			row.fileIndex = null;
			if (row.rowStatus !== "D" && row.fileChanged === "Y") {
				const f = scwin.fileMap[row.uid];
				if (f) {
					row.fileIndex = files.length;
					files.push(f);
				}
			}
		}
	}

	const formData = new FormData();

	// dataList 별 rows 파트 (빈 payload 는 제외 — 파트 이름은 원래 인덱스 기준 유지)
	for (let li2 = 0; li2 < listPayloads.length; li2++) {
		if ($c.util.isEmpty(listPayloads[li2])) continue;
		const dataListId = scwin.__partName(opts.dataListId, li2, "rows");
		const newPayload = {};
		newPayload[dataListId] = listPayloads[li2];
		formData.append(dataListId, new Blob([JSON.stringify(newPayload)], { type: "application/json;charset=UTF-8" }), `${dataListId}.json`);
	}

	// dataMap 별 파트 — 데이터를 JSON Blob 로 추가해서 전송한다.
	const dataMaps = scwin.__toArray(opts.dataMap);
	for (let mi = 0; mi < dataMaps.length; mi++) {
		const data = dataMaps[mi].getJSON();
		if ($c.util.isEmpty(data)) continue;
		const dataMapId = scwin.__partName(opts.dataMapId, mi, "data");
		formData.append(dataMapId, new Blob([JSON.stringify(data)], { type: "application/json;charset=UTF-8" }), `${dataMapId}.json`);
	}

	for (let j = 0; j < files.length; j++) {
		formData.append("files", files[j], files[j].name);
	}

	try {
		const res = await fetch(opts.saveUrl, { method: "POST", body: formData }).then(function (r) {
			if (!r.ok) throw new Error("HTTP " + r.status);
			return r.json();
		});

		scwin.clearFileMap();

		if (typeof opts.onSuccess === "function") opts.onSuccess(res);
		if (typeof opts.onAfterSave === "function") await opts.onAfterSave(res);
	} catch (e) {
		if (typeof opts.onError === "function") opts.onError(e);
		else $c.win.alert("저장 실패: " + e.message);
	}
};

// ═══════════════════════════════════════════════════════════════
// dataMap 기반 (flat 폼 — 여러 테이블에 필드 분산)
// FormData 규칙: 텍스트는 {dataMapId} JSON Blob 파트,
//               파일은 files 다중 append + "{fieldKey}_file_index"(files 내 인덱스)로 매칭
// ═══════════════════════════════════════════════════════════════

/**
 * @method
 * @name attachFileToMap
 * @description dataMap 의 특정 fieldKey 에 파일 첨부. 파일명은 dataMap.set 으로 자동 반영 (input ref 자동 갱신)
 * @param {string} fieldKey  dataMap 의 key
 * @hidden N
 * @param {object} dataMap   대상 dataMap
 */
scwin.attachFileToMap = function (fieldKey, dataMap) {
	scwin.ctx = { fieldKey: fieldKey, dataMap: dataMap };
	if (!mpu_hidden.dom || !mpu_hidden.dom.inputZone) {
		$c.win.alert("업로드 초기화 오류"); return;
	}

	mpu_hidden.dom.inputZone.value = "";
	mpu_hidden.dom.inputZone.click();
};

/**
 * @method
 * @name detachFileFromMap
 * @description dataMap 파일 제거 — 파일명 비우고 fileMap 정리
 * @param {string} fieldKey  dataMap 의 key
 * @hidden N
 * @param {object} dataMap   대상 dataMap
 */
scwin.detachFileFromMap = function (fieldKey, dataMap) {
	if (scwin.fileMap[fieldKey]) delete scwin.fileMap[fieldKey];
	dataMap.set(fieldKey, "");
};

/**
 * @method
 * @name loadMapForm
 * @description GET → dataMap.setJSON — 모든 input(ref) 자동 갱신
 * @param opts.dataMap   대상
 * @hidden N
 * @param opts.listUrl   GET API
 * @param opts.dataKey   응답 안 데이터 오브젝트 key (기본 "data")
 * @param opts.onSuccess (res)
 * @param opts.onError
 */
scwin.loadMapForm = async function (opts) {
	try {
		const res = await fetch(opts.listUrl).then(function (r) {
			if (!r.ok) throw new Error("HTTP " + r.status);
			return r.json();
		});

		const data = res[opts.dataKey || "data"] || {};
		opts.dataMap.setJSON(data);

		if (typeof opts.onSuccess === "function") opts.onSuccess(res);
	} catch (e) {
		if (typeof opts.onError === "function") opts.onError(e);
		else $c.win.alert("조회 실패: " + e.message);
	}
};

/**
 * @method
 * @name saveMapForm
 * @description dataMap 텍스트 + fileMap 파일을 하나의 FormData 로 저장.
 * dataMap/dataList 는 단일 또는 배열(멀티)로 전달할 수 있다.
 * FormData 규칙:
 *   - dataMap  별 파트: dataMap JSON Blob ("{파트명}.json", application/json)
 *   - dataList 별 파트: opts.dataList 지정 시 { "{파트명}": rows } JSON Blob (전체 로우)
 *   - files 파트: fileMap 의 파일들을 다중 append
 *   - "{fieldKey}_file_index" 파트: 해당 필드 파일의 files 내 인덱스 (서버 매칭용)
 * 파트 이름: dataMapId/dataListId(단일 문자열 또는 병렬 배열) 우선, 미지정 시 data, data2… / rows, rows2…
 * @param {Object|Array} opts.dataMap    단일 dataMap 또는 배열(멀티)
 * @hidden N
 * @param opts.saveUrl
 * @param {string|Array} opts.dataMapId  dataMap 파트 이름 — 단일 문자열 또는 병렬 배열 (기본 data, data2…)
 * @param {Object|Array} opts.dataList   (선택) 함께 전송할 dataList — 단일 또는 배열, 전체 로우를 파트로 추가
 * @param {string|Array} opts.dataListId dataList 파트 이름 — 단일 문자열 또는 병렬 배열 (기본 rows, rows2…)
 * @param opts.onValidate  (data) → err|null — 단일 dataMap 이면 해당 JSON, 멀티면 JSON 배열이 전달됨
 * @param opts.onSuccess   (res)
 * @param opts.onAfterSave (res)
 * @param opts.onError
 * @example
// 1) 단일 dataMap 폼 — 파일은 attachFileToMap("photo", dma_form) 으로 첨부해 둔 것 자동 동봉
//    → FormData 파트: data, photo_file_index, files
udc_saver.getScope().saveMapForm({
    dataMap : dma_form,
    saveUrl : "/api/x/save-form",
    onValidate : function (data) { return $c.util.isEmpty(data.userNm) ? "이름을 입력하세요." : null; },
    onAfterSave : async function (res) { await scwin.searchDetail(); }
});

// 2) 멀티 dataMap + dataList 동봉 — onValidate 에는 JSON "배열"([기본정보, 부가정보])이 전달됨
//    → 파트: basic, data2, rows, {fieldKey}_file_index, files
udc_saver.getScope().saveMapForm({
    dataMap : [dma_basic, dma_extra],
    dataMapId : ["basic"],                // 두 번째는 자동 "data2"
    dataList : dlt_subItems,              // 전체 로우가 rows 파트로 동봉
    saveUrl : "/api/x/save-form",
    onValidate : function (arr) { return $c.util.isEmpty(arr[0].userNm) ? "이름을 입력하세요." : null; }
});
 */
scwin.saveMapForm = async function (opts) {
	const dataMaps = scwin.__toArray(opts.dataMap);
	const dataJsons = dataMaps.map(function (dm) { return dm.getJSON(); });

	if (typeof opts.onValidate === "function") {
		// 하위호환: 단일 dataMap 이면 JSON 객체, 멀티면 JSON 배열 전달
		const err = opts.onValidate(dataJsons.length > 1 ? dataJsons : dataJsons[0]);
		if (err) {
			$c.win.alert(err); return;
		}
	}

	const formData = new FormData();

	// dataList(들)가 있는 경우 각자 rows 파트에 담아 전송한다. (빈 목록 제외 — 파트 이름은 원래 인덱스 기준)
	const dataLists = scwin.__toArray(opts.dataList);
	for (let li = 0; li < dataLists.length; li++) {
		const payload = dataLists[li].getAllJSON();
		if ($c.util.isEmpty(payload)) continue;
		const dataListId = scwin.__partName(opts.dataListId, li, "rows");
		const newPayload = {};
		newPayload[dataListId] = payload;
		formData.append(dataListId, new Blob([JSON.stringify(newPayload)], { type: "application/json;charset=UTF-8" }), `${dataListId}.json`);
	}

	// 텍스트 필드 — dataMap 별 JSON Blob 파트
	for (let mi = 0; mi < dataJsons.length; mi++) {
		if ($c.util.isEmpty(dataJsons[mi])) continue;
		const dataMapId = scwin.__partName(opts.dataMapId, mi, "data");
		formData.append(dataMapId, new Blob([JSON.stringify(dataJsons[mi])], { type: "application/json;charset=UTF-8" }), `${dataMapId}.json`);
	}

	const keys = Object.keys(scwin.fileMap);

	// 파일 — files 다중 append + "{fieldKey}_file_index" 로 files 내 인덱스 전달(서버 매칭용)
	for (let f in scwin.fileMap) {
		let file = null;
		if (scwin.fileMap.hasOwnProperty(f)) {
			file = scwin.fileMap[f];
		}

		if (file) {
			formData.append(`${f}_file_index`, keys.indexOf(f));
			formData.append("files", file, file.name);
		}
	}

	try {
		const res = await fetch(opts.saveUrl, { method: "POST", body: formData }).then(function (r) {
			if (!r.ok) throw new Error("HTTP " + r.status);
			return r.json();
		});

		scwin.clearFileMap();

		if (typeof opts.onSuccess === "function") opts.onSuccess(res);
		if (typeof opts.onAfterSave === "function") await opts.onAfterSave(res);
	} catch (e) {
		if (typeof opts.onError === "function") {
			opts.onError(e);
		} else {
			$c.win.alert("저장 실패: " + e.message);
		}
	}
};
